param([Parameter(Mandatory=$true)][string]$RepoPath,
      [Parameter(Mandatory=$true)][int]$PipelinePid,
      [Parameter(Mandatory=$true)][string]$CreationUtc,
      [string]$ExpectedCommandTag='t0013_changed_audit_run.ps1')
$ErrorActionPreference='Stop'
$root = (Resolve-Path -LiteralPath $RepoPath).Path
$output = Join-Path $root 'build/t0013_changed_audit'
$expected = [datetime]::Parse($CreationUtc).ToUniversalTime()
$encoding = [System.Text.UTF8Encoding]::new($false)
function Write-Sample($row) {
    $json = $row | ConvertTo-Json -Depth 5 -Compress
    [System.IO.File]::WriteAllText((Join-Path $output 'resource_state.json'),$json+"`n",$encoding)
    [System.IO.File]::AppendAllText((Join-Path $output 'resource_monitor.jsonl'),$json+"`n",$encoding)
}
while ($true) {
    try {
        $all = @(Get-CimInstance Win32_Process)
        $pipeline = $all | Where-Object ProcessId -eq $PipelinePid
        $utc = (Get-Date).ToUniversalTime().ToString('o')
        if (-not $pipeline) { Write-Sample @{utc=$utc;event='pipeline_exited';pipeline_pid=$PipelinePid}; break }
        if ([math]::Abs(($pipeline.CreationDate.ToUniversalTime()-$expected).TotalSeconds) -gt 1 -or
            $pipeline.CommandLine -notmatch ('task.py lock.*T0013.*'+[regex]::Escape($ExpectedCommandTag))) {
            Write-Sample @{utc=$utc;event='identity_mismatch';pipeline_pid=$PipelinePid;attention=$true}; break
        }
        $ids = [System.Collections.Generic.HashSet[int]]::new()
        [void]$ids.Add($PipelinePid)
        do {
            $before=$ids.Count
            foreach ($process in $all) {
                if ($ids.Contains([int]$process.ParentProcessId)) {
                    $ancestor=$all | Where-Object ProcessId -eq $process.ParentProcessId
                    if ($ancestor -and $process.CreationDate -ge $ancestor.CreationDate) { [void]$ids.Add([int]$process.ProcessId) }
                }
            }
        } while ($ids.Count -gt $before)
        $processes = @()
        foreach ($process in $all) {
            if ($ids.Contains([int]$process.ProcessId)) {
                $live=Get-Process -Id $process.ProcessId -ErrorAction SilentlyContinue
                if ($live) { $processes+=@{pid=$live.Id;parent_pid=$process.ParentProcessId;creation_utc=$process.CreationDate.ToUniversalTime().ToString('o');command=$process.CommandLine;
                    private_gib=[math]::Round($live.PrivateMemorySize64/1GB,3);
                    working_gib=[math]::Round($live.WorkingSet64/1GB,3);cpu_seconds=$live.CPU} }
            }
        }
        $os=Get-CimInstance Win32_OperatingSystem
        $memory=Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory
        $free=[math]::Round($os.FreePhysicalMemory/1MB,3)
        $commit=[math]::Round(($memory.CommitLimit-$memory.CommittedBytes)/1GB,3)
        $vram=(& nvidia-smi --query-gpu=memory.used,memory.free,utilization.gpu --format=csv,noheader,nounits 2>$null)
        $lease=Get-Content -LiteralPath (Join-Path $env:USERPROFILE '.ctf-fusion/locks/cpu.json') -Raw | ConvertFrom-Json
        Write-Sample @{utc=$utc;event='sample';pipeline_pid=$PipelinePid;monitor_pid=$PID;
                      physical_available_gib=$free;commit_available_gib=$commit;gpu_readonly=$vram;cpu_lease_task=$lease.task;cpu_lease_pid=$lease.pid;
                      attention=($free -lt 4 -or $commit -lt 8);processes=$processes;
                      policy='passive_only_no_kill_no_restart_no_resource_change'}
    } catch {
        Write-Sample @{utc=(Get-Date).ToUniversalTime().ToString('o');event='monitor_error';attention=$true;error=$_.Exception.Message}
    }
    Start-Sleep -Seconds 15
}

t0013_changed_finish.ps1.text:
param([Parameter(Mandatory=$true)][string]$RepoPath)
$ErrorActionPreference='Stop'
$taskRoot=(Resolve-Path -LiteralPath $RepoPath).Path
Set-Location -LiteralPath $taskRoot
$identity='76a19544caa2caa667b55f41c499a8baac12d01304c25f6985418e298790d7e7'
$output=Join-Path $taskRoot 'build/t0013_changed_audit'
$encoding=[System.Text.UTF8Encoding]::new($false)
function Write-State($row) {
    [System.IO.File]::WriteAllText((Join-Path $output 'finish_state.json'),($row|ConvertTo-Json -Depth 5)+"`n",$encoding)
}
try {
    $receipt=Get-Content -LiteralPath 'build/t0013_changed/LAUNCH_RECEIPT.json' -Raw | ConvertFrom-Json
    if ($receipt.identity -ne $identity -or -not $receipt.verified) {throw 'Collection launch not verified'}
    $wrapper=@($receipt.processes | Where-Object CommandLine -Match 'tools/repo/task.py lock')[0]
    $expected=if ($wrapper.creation_utc -is [datetime]) {$wrapper.creation_utc.ToUniversalTime()} else {[datetime]::Parse([string]$wrapper.creation_utc).ToUniversalTime()}
    $self=Get-CimInstance Win32_Process -Filter "ProcessId=$PID"
    Write-State @{utc=(Get-Date).ToUniversalTime().ToString('o');stage='waiting_for_exact_collection_chain';identity=$identity;pid=$PID;birth=$self.CreationDate.ToUniversalTime().ToString('o');command=$self.CommandLine;parent=$self.ParentProcessId;wrapper_pid=$wrapper.ProcessId}
    while ($true) {
        $live=Get-CimInstance Win32_Process -Filter "ProcessId=$($wrapper.ProcessId)"
        if (-not $live) {break}
        if ($live.CreationDate.ToUniversalTime() -ne $expected -or $live.CommandLine -notmatch 'task.py lock.*T0013.*t0013_changed_run.ps1') {break}
        Start-Sleep -Seconds 15
    }
    if (-not (Test-Path -LiteralPath 'build/t0013_changed/COMPLETE.json')) {throw 'Collection did not complete successfully; do not start audit'}
    $complete=Get-Content -LiteralPath 'build/t0013_changed/COMPLETE.json' -Raw | ConvertFrom-Json
    if ($complete.identity -ne $identity -or -not $complete.collection_success -or $complete.physical_continuations -ne 2898) {throw 'Wrong collection receipt'}
    if (Test-Path -LiteralPath 'build/t0013_changed/AUDIT_COMPLETE.json') {throw 'Audit already complete; do not restart'}
    if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE '.ctf-fusion/locks/cpu.json')) {throw 'CPU lane now occupied; no competing audit launch'}
    if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE '.ctf-fusion/locks/gpu.json')) {throw 'GPU lease present; no concurrent formal stage'}
    $binding=Get-Content -LiteralPath 'build/t0013_changed_audit/FROZEN_AUDIT.json' -Raw | ConvertFrom-Json
    foreach ($entry in $binding.sources.PSObject.Properties) {
        $path=Join-Path (Split-Path (Split-Path $taskRoot -Parent) -Parent) $entry.Name
        if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value) {throw "Audit source changed: $($entry.Name)"}
    }
    Write-State @{utc=(Get-Date).ToUniversalTime().ToString('o');stage='acquiring_serial_audit_lease';identity=$identity;pid=$PID}
    & $env:T0013_PYTHON tools/repo/task.py lock --task T0013 --wait 0 cpu -- pwsh -NoProfile -ExecutionPolicy Bypass -File ../../t0013_changed_audit_run.ps1 1> build/t0013_changed_audit/audit.log 2> build/t0013_changed_audit/audit.stderr
    if ($LASTEXITCODE -ne 0) {throw "Independent audit exited $LASTEXITCODE; retained raw untouched"}
    if (-not (Test-Path -LiteralPath 'build/t0013_changed/AUDIT_COMPLETE.json')) {throw 'Missing successful audit receipt'}
    Write-State @{utc=(Get-Date).ToUniversalTime().ToString('o');stage='audit_and_statistics_complete';identity=$identity;pid=$PID}
} catch {
    Write-State @{utc=(Get-Date).ToUniversalTime().ToString('o');stage='attention';identity=$identity;pid=$PID;error=$_.Exception.Message}
    throw
}
